#include <iostream>
#include <sstream>

int main() {
    std::istringstream entrada{"5 11z 2"};
    int valor = 0;
    while (entrada >> valor) {
        std::cout << "Valeur: " << valor << "\n";
    }
    if (entrada.bad()) {
        std::cout << "Échec du flux";
    } else if (entrada.eof()) {
        std::cout << "Fin";
    } else {
        std::cout << "Format invalide";
    }
    return 0;
}
